import random,math,json,statistics
from collections import Counter,defaultdict
from functools import lru_cache
from vs import dsl,corpus,ivtff
from tests.test_dsl import page
PAIRS=[('y','q'),('n','q'),('y','o'),('n','o'),('y','ch'),('n','ch'),('y','d'),('n','d')]

def prep(pages):
 ts=[t for t in dsl.tokens(pages) if t['unit']=='P' and t['w'] and not ivtff.uncertain(t['w']) and ivtff.segment(t['w'])]
 groups=defaultdict(list)
 for i,t in enumerate(ts):groups[t['page'],t['pfl'],t['n'],t['k']].append(i)
 edge=[(a,b) for run in dsl.runs_of(ts) for a,b in zip(run,run[1:])]
 ix={(t['line'],t['k']):i for i,t in enumerate(ts)}
 pairs=[(ix[a['line'],a['k']],ix[b['line'],b['k']]) for a,b in edge]
 return ts,list(groups.values()),pairs

def calc(pages,draws=99,seed=23):
 ts,groups,edges=prep(pages)
 @lru_cache(None)
 def first(w):return ivtff.segment(w)[0]
 @lru_cache(None)
 def last(w):return ivtff.segment(w)[-1]
 words=[t['w'] for t in ts]; gp={i:g for g in groups for i in g}
 movable=sum(len({words[i] for i in g})>1 for g in groups)
 if movable<30: raise ValueError('fewer than 30 movable groups')
 start={i:Counter(first(words[j]) for j in g) for g in groups for i in g};end={i:Counter(last(words[j]) for j in g) for g in groups for i in g}
 expected=[sum(end[a][x]/len(gp[a])*start[b][y]/len(gp[b]) for a,b in edges) for x,y in PAIRS]
 def counts(w):
  c=Counter((last(w[a]),first(w[b])) for a,b in edges);return [c[p] for p in PAIRS]
 def score(c):return sum((v-e)**2/(e+1) for v,e in zip(c,expected))
 obs=counts(words); st=score(obs);rng=random.Random(seed); simulated=[]; sm=[0]*8
 for _ in range(draws):
  sh=words[:]
  for g in groups:
   ws=[words[i] for i in g];rng.shuffle(ws)
   for i,w in zip(g,ws):sh[i]=w
  cs=counts(sh);simulated.append(score(cs));sm=[a+b for a,b in zip(sm,cs)]
 return {'tokens':len(ts),'edges':len(edges),'groups':len(groups),'movable_groups':movable,'score':st,'p':(1+sum(s>=st-1e-12 for s in simulated))/(draws+1),'observed':obs,'expected':expected,'permutation_mean':[x/draws for x in sm]}

def synthetic(seed,mode):
 rng=random.Random(seed); pages=[]
 for p in range(8):
  rows=[]
  for line in range(20):
   shared=rng.choice([0,1]); prev=rng.choice([0,1]); ws=[]
   for j in range(8):
    # Position and page marginals vary, but every glyph choice is independent under null.
    if mode=='null': a=(rng.random()<(.25+.5*((p+j)%2))); b=(rng.random()<(.25+.5*((p+2*j)%2)))
    elif mode=='markov':
     a=prev if rng.random()<.9 else not prev; b=rng.choice([0,1]); prev=b
    else:a=b=shared
    ws.append(('q' if a else 'o')+'a'+('y' if b else 'n'))
   rows.append(ws)
  pages.append(page(f'p{p}',rows,order=p))
 return pages

if __name__=='__main__':
 out={'practice':{},'synthetic':{}}
 for kind in ('null','markov','latent_line'):
  vals=[calc(synthetic(i,kind),39,900+i)['p'] for i in range(20)]
  out['synthetic'][kind]={'p_values':vals,'passes':sum(p<=.05 for p in vals)}
 sparse=[page('s', [['qay','oan']*(n//2)+(['qay'] if n%2 else []) for n in range(3,83)])]
 try:calc(sparse,39);out['sparse']='unexpectedly accepted'
 except ValueError as e:out['sparse']=str(e)
 for tr in ('zl','it'):
  train,ev=corpus.split_pages('practice',tr)
  for name,pages in [('train',train),('eval',ev)]:out['practice'][tr+'-'+name]=calc(pages,99)
 print(json.dumps(out,indent=2))
